import React, { useState } from "react";
import Background from "../components/Background";
import "../styles/Support.css";

const faqsData = [
  {
    question: "Làm sao để tạo landing page nhanh chóng?",
    answer: "Bạn chỉ cần chọn template, kéo thả các thành phần và xuất bản. Không cần kỹ năng code."
  },
  {
    question: "Có thể tùy chỉnh layout không?",
    answer: "Có, LandingHub cho phép chỉnh sửa mọi phần tử, màu sắc, font chữ và bố cục."
  },
  {
    question: "Hỗ trợ kỹ thuật như thế nào?",
    answer: "Chúng tôi có chat trực tuyến và form liên hệ 24/7, đảm bảo phản hồi nhanh chóng."
  }
];

const Support = () => {
  const [openIndex, setOpenIndex] = useState(null);
  const toggleFAQ = (index) => {
    setOpenIndex(openIndex === index ? null : index);
  };

  return (
    <Background showShapes={false} fullWidth={true}>
      <div className="support-page">

        {/* Hero Section */}
        <section className="support-hero">
          <h1>Cần hỗ trợ? Chúng tôi luôn sẵn sàng!</h1>
          <p>LandingHub cung cấp mọi giải pháp để bạn tạo landing page chuyên nghiệp.</p>
        </section>

        {/* FAQ Section */}
        <section className="faq-section">
          <h2>Câu hỏi thường gặp</h2>
          <div className="faq-list">
            {faqsData.map((faq, idx) => (
              <div
                key={idx}
                className={`faq-card ${openIndex === idx ? "open" : ""}`}
                onClick={() => toggleFAQ(idx)}
              >
                <div className="faq-question">{faq.question}</div>
                <div className="faq-answer">{faq.answer}</div>
              </div>
            ))}
          </div>
        </section>

        {/* Contact / Live Support */}
        <section className="contact-section">
          <h2>Liên hệ hỗ trợ trực tuyến</h2>
          <form className="contact-form">
            <input type="text" placeholder="Họ tên" required />
            <input type="email" placeholder="Email" required />
            <textarea placeholder="Nội dung" required></textarea>
            <button type="submit" className="btn-submit">Gửi yêu cầu</button>
          </form>
        </section>

        {/* CTA Section */}
        <section className="cta-support">
          <h2>Chúng tôi luôn ở bên bạn</h2>
          <p>Đừng ngần ngại liên hệ để nhận được hỗ trợ nhanh nhất!</p>
        </section>

      </div>
    </Background>
  );
};

export default Support;
